function GachaponEntry:OnInitialize()
    return CoWaitDo(function()
     
        self._tabResult = GachaponShared.TabResult ~= nil and GachaponShared.TabResult or nil
        self._popResult = GachaponShared.PopUp ~= nil and GachaponShared.PopUp or nil
        
        ---@type CriWare.CriManaMovieControllerForUI
        local controllerForUI = self.MovieControllerUI
        if controllerForUI and controllerForUI.player then
            controllerForUI.player.statusChangeCallback = nil
        end
        if self.VideoPreviewMovie and self.VideoPreviewMovie.player then
            self.VideoPreviewMovie.player.statusChangeCallback = nil
        end

        CfUtils.SetActive(self.bg, true)
        
        self:AddListener()
        --self:FakeData()

    end)
end

function GachaponEntry:DoInitialize_()
    self.GachaponComp = GachaponUtils.GetGachaponComp()
    self:SetAllGachapon()

    local param = CfUtils.DialogSafeParameters(self.controller)
    for _, poolId in ipairs(string.split2(checkString(param.openedPools), ',')) do
        self._openedPoolMap[checkInt(poolId)] = true
    end
    
    -- 外部跳转进入指定卡池
    if isSet(param, "jumpPool") then
        local jump = nil
        for i = 1, #self.GachaponComp.AllGachapon do
            if self.GachaponComp.AllGachapon[i].poolId == param.jumpPool then
                jump = i - 1
                break
            end
        end
        param.jumpIndex = jump
    end

    self._jumpIndex = (isSet(param, "jumpIndex")) and param.jumpIndex or nil
    -- 读取上次离开界面时的索引位置
    if param.selectIndex ~= nil then
        self._jumpIndex = param.selectIndex
        self._isSelectFirst = true
    end

    local jumpIndex = KCookie.Get("DRAW_CARD_POOL_INDEX")
    if jumpIndex then
        self._jumpIndex = checkNumber(jumpIndex)
        KCookie.RemoveAllListener("DRAW_CARD_POOL_INDEX")
    end

    if GachaponShared.RecordJump ~= nil then
        self._jumpIndex = GachaponShared.RecordJump
        GachaponShared.RecordJump = nil
    end
    
    if GachaponShared.RecordPoolId ~= nil then
        local jump = nil
        for i = 1, #self.GachaponComp.AllGachapon do
            if self.GachaponComp.AllGachapon[i].poolId == GachaponShared.RecordPoolId then
                jump = i - 1
                break
            end
        end
        self._jumpIndex = jump
        GachaponShared.RecordPoolId = nil
    end

    if self._jumpIndex == nil then
        self._jumpIndex = 0
    end

    -- init resItems
    if self._jumpIndex >= #self.GachaponComp.AllGachapon then
        self._jumpIndex = 0
    end
    local pool = self.GachaponComp.AllGachapon[self._jumpIndex + 1] or {}
    self._resItems = GachaponUtils.GetPoolCurrencyList(pool)
    --self._gachaCam = URPCameraController.mainCamera
    self:RefreshResNode(self._resItems)
end

function GachaponEntry:SetAllGachapon()
    self.AllGachapon= {}
    for i, v in pairs(self.GachaponComp.AllGachapon) do
        -- 非核心装备和 isUnlock ==1 的显示
        if checkInt(v.isUnlock) == 1 or not GachaponUtils.IsEquipType(v.poolType) then
            self.AllGachapon[#self.AllGachapon+1] = v
        end
    end
end

function GachaponEntry:OnFinalize()
    return CoWaitDo(function()
        local initParams = CfUtils.DialogSafeParameters(self.controller)
        initParams.selectIndex = self._selectIndex
        initParams.contentPosY = self.Content.anchoredPosition.y
        initParams.openedPools = table.concat(table.keys(self._openedPoolMap), ',')

        if self._animCo ~= nil then
            cs_coroutine.stop(self._animCo)
            self._animCo = nil
        end
        UIRaycastBlocker:RemoveCondition(REFRESH_BLOCKER_NAME)
        -- 关闭定时器
        if not isNull(self._timeDown) then
            for _, timer in pairs(self._timeDown) do
                CDTimerModule.GetInstance():RemoveCD(timer)
            end
            self._timeDown = nil
        end
        if self._openCo ~= nil then
            cs_coroutine.stop(self._openCo)
            self._openCo = nil
        end
        if self._openDoorCo ~= nil then
            cs_coroutine.stop(self._openDoorCo)
            self._openDoorCo = nil
        end
        if self._refreshCharInfoCo  ~= nil  then
            cs_coroutine.stop(self._refreshCharInfoCo)
            self._refreshCharInfoCo = nil
        end

        if self._co then
            MonoHelper.RemoveUpdateListener(self._co)
            self._co = nil
        end

        UIRaycastBlocker:RemoveCondition(OPENING_BLOCKER_NAME)

        for objPath, _ in pairs(self._loadedObjects or {}) do
            GachaponShared:DisposeSingle(objPath)
        end

        --self:BlurCamera(CS.CameraCustomData.DepthOfFieldMode.Off, 50, 10)
        CfUtils.SetActive(URPCameraController.mainCamera, true)

        CfUtils.SetTopActive(true)

        self:PoolVideoStop_()
        if self.VideoPreviewMovie and self.VideoPreviewMovie.player then
            self.VideoPreviewMovie.player.statusChangeCallback = nil
        end

        -- GachaponUtils.SetUICameraProjection(true)
        self:RemoveListener()
        GachaponShared:DisposeEnterAnim(self._usedEnterAnim)
        if not self._isNeedSkipOnHide then
            GachaponShared:DisposeAll()
            CfUtils.CookieSave(Constants.UICacheDataKeys.GACHAPON_ENTRY_CAMP_SELECT_INDEX, nil)
        end
        GachaponShared:SetTempContent(nil)

        self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end)
end

