--- 选择卡池列表（process-2）
---@param idx integer @ 卡池列表index，范围：0 - self.Content:GetChildCount()
function GachaponEntry:OnSelectButton(idx)
    assert(type(idx) == 'number')
    if self.Content.childCount < idx + 1 then
        printInfo("not enough gachapon %d", idx)
        return
    end
    if self._selectIndex == idx then
        return
    end
    -- if self._isSelectFirst then
    --     CfUtils.PlayAnimator(self.RotatePanel, "GachaponEntry_Root_Rotate_Again")
    -- end
    
    local itemIns = nil
    local cellNode = nil
    local selectNode = nil
    -- update old selectCell
    if self._selectIndex ~= nil then
        cellNode = self.Content:GetChild(self._selectIndex)
        itemIns = cellNode.transform:Find("BtnNode").gameObject
        selectNode = itemIns.transform:Find("ImgBannerSelect").gameObject
        CfUtils.SetActive(selectNode,false)
        CfUtils.SetActive(itemIns.transform:Find("ImgShadow"),false)
        CfUtils.PlayAnimator(selectNode, "CellSelect_Loop")
        CfUtils.PlayAnimation(cellNode, AnimName.CELL_CANCEL)
    end
    -- update new selectCell
    self._selectIndex = idx
    cellNode = self.Content:GetChild(idx)
    itemIns = cellNode.transform:Find("BtnNode").gameObject
    selectNode = itemIns.transform:Find("ImgBannerSelect").gameObject
    CfUtils.SetActive(selectNode,true)
    CfUtils.SetActive(itemIns.transform:Find("ImgShadow"),true)
    CfUtils.PlayAnimator(selectNode, "CellSelect_Open")
    CfUtils.PlayAnimation(cellNode, AnimName.CELL_SELECT)

    -- 打点上报
    local pool = self.AllGachapon[self._selectIndex + 1]
    if pool then
        xRecord.record('3-030', string.fmt('click_slot_%1', checkInt(pool.poolId)))
    end

    -- update content bg
    self:RefreshGachaponByIndex(idx)
end

--- 刷新卡池相关内容（process-3）
function GachaponEntry:RefreshGachaponByIndex(idx)
    assert(type(idx) == 'number')
    
    
    --替换为入场动画
    --self.bg:LoadSprite(string.format(GachaponConstants.EntryResPath,pool.poolId,setting.bgType))
    --GachaponUtils.LoadSpriteAsync(img,string.format(GachaponConstants.EntryResPath,pool.poolId,setting.btnType),true)

    if self._animCo ~= nil then
        cs_coroutine.stop(self._animCo)
    end

    self._animCo = cs_coroutine.start(function()
        
        UIRaycastBlocker:AddCondition(REFRESH_BLOCKER_NAME)
        
        local i = idx + 1
        ---@type GachaponDojo
        local pool = self.AllGachapon[i]
        logt(pool, 'gachapon_pool_' .. i)
        -- printInfo("anim %d", checkInt(pool.poolId))
        
        self._resItems = GachaponUtils.GetPoolCurrencyList(pool)
        self._poolType = pool.poolType
        self._poolId = pool.poolId
        self._pool = pool
        local resourceId = checkInt(pool.resource)
        self:RefreshCharInfo()               -- 刷新卡池立绘位置
        self:RefreshResNode(self._resItems)  -- 刷新货币栏
        self:RefreshBtnInfo()                -- 刷新界面中的控制按钮
        self:RefreshTimeInfo()               -- 刷新卡池剩余时间
        
        -- 加载内容prefab页
        local path = string.format(GachaponConstants.EntryResPrefabPath,resourceId,tostring(pool.bgType))
        if CfUtils.IsBundleResourceExist(path) then
            GachaponShared:LoadModel(path)
            while not GachaponShared:GetModel(path) do
                CoYield()
            end
        else
            printError('gachapon [%s] is not exist!', path)
        end

        -- 更新内容prefab页
        if self.bg.transform.childCount ~= 0 then
            local prev = self.bg.transform:GetChild(self.bg.transform.childCount - 1)
            CfUtils.SetActive(prev, false)
        end
        self.bg.transform.localPosition =  CS.UnityEngine.Vector3.zero
        local model = GachaponShared:GetModel(path)
        if isNotNull(model) then

            self._modelBg = model
           
            model.transform:SetParent(self.bg.transform)
            model.transform.localPosition = CS.UnityEngine.Vector3.zero
            model.transform.localScale = CS.UnityEngine.Vector3.one
            model.transform.sizeDelta = CS.UnityEngine.Vector2.zero
            model.transform.rotation = self.bg.transform.rotation

            model.transform:SetAsLastSibling()
            if not self._isFinish then
                CfUtils.SetActive(self.AnimRoot, true)
                CfUtils.SetActive(model, false)
                --local animTime = CfUtils.GetAnimatorTime(self.AnimRoot, "Gachapon_Root_Enter")
                --if KTool.UNITY_IOS() or KTool.UNITY_ANDROID() then
                --    --真机设备增加延迟时间
                --    animTime = 0.5
                --end
                --coroutine.yield( CS.UnityEngine.WaitForSeconds(animTime))
            end

            CfUtils.SetActive(model, true)
            --首次进入 Gachapon%d_Enter  第二次播放 Gachapon%d_Again
            if self._isSelectFirst then
                if self._openedPoolMap[checkInt(self._poolId)] then
                    CfUtils.PlayAnimator(model, string.format("Gachapon%d_Loop", resourceId))
                else
                    CfUtils.PlayAnimator(model, string.format("Gachapon%d_Again", resourceId))
                end
                self._openedPoolMap[checkInt(self._poolId)] = true
            else
                CfUtils.PlayAnimator(model, string.format("Gachapon%d_Enter", resourceId))
                self._openedPoolMap[checkInt(self._poolId)] = true
            end
                    
            if self._usedEnterAnim == nil then
                self._usedEnterAnim = {}
            end
            table.insert(self._usedEnterAnim, path)
        end

        -- 更新内容prefab页
        self:UpdateContentPrefab(pool, model)
        
        --入场以后打开结果
        if self._popResult ~= nil and self._popResult then
            CoYield()
            GachaponShared.TabResult = nil
            GachaponShared.PopUp = nil
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = self._tabResult } })
            self._popResult = nil

        else
            -- 是否需要 打开之前的友情抽卡结果弹窗
            local initParams = CfUtils.DialogSafeParameters(self.controller)
            if initParams.reopenFriendshipResultData then
                CfUtils.PlayAnimator(model, string.format("Gachapon%d_Loop", resourceId))
                CoYield() -- 不等一帧的话，下面弹窗截屏就会是黑的了
                local rewardCardResult = initParams.reopenFriendshipResultData
                CfUtils.DialogOpen(Constants.UITypeIds.GachaponFriendshipResultDialog, {result = rewardCardResult, isReopenMode = true, needReopenCb = function()
                    initParams.reopenFriendshipResultData = rewardCardResult
                end})
                initParams.reopenFriendshipResultData = nil

            else
                coroutine.yield(Yielders.GetWaitForSeconds(0.4))
            end
        end
        self._isFinish = true
        UIRaycastBlocker:RemoveCondition(REFRESH_BLOCKER_NAME)

        self._animCo = nil
    end)
end

--- 更新内容prefab页
---@param pool GachaponDojo
---@param model UnityEngine.GameObject @ 内容页prefab
function GachaponEntry:UpdateContentPrefab(pool, model)
    local activityData = checkTable(pool.activity)
    -- 如果实在引导中 ， 不检测下载 
    if not GuideUtils.IsInGuiding() then
            ---@type GachaponDojo
        if not string.isEmpty(pool.video) then
            local poolVideoPath = GameUtils.GetManaPath(string.fmt("Movie/%1.usm", pool.video))
            local File = CS.System.IO.File
            local isExists = File.Exists(poolVideoPath)
            if not isExists then                 
                local ThirdDownloadManager = import("Game.Entry.ThirdDownloadManager"):GetInstance()
                local isSupport = ThirdDownloadManager:IsSupportThirdPackage()
                if isSupport then
                    local PlayerPrefsUtility = CS.Engine.Tools.PlayerPrefsUtility
                    local ThirdPackageDownloaded = "ThirdPackageDownloaded"
                    local version =  PlayerPrefsUtility.GetEncryptedString(ThirdPackageDownloaded , "")
                    if string.len(version) < 3  then
                        UIModule.OpenDialog({ id = Constants.UITypeIds.ThirdPackageDownloadDialog})
                        return
                    end
                end
            end
        end
    end
   
    -- 新手引导卡池隐藏 GuidePoodId
