        local ImgSlogan = model.transform:Find("ImgSlogan")
        if not isNull(ImgSlogan) then
            CfUtils.SetActive(ImgSlogan , false)
        end

    -------------------------------------------------
    -- 更新点数的UI
    -- elseif pool.poolType == GachaponConstants.PoolType.PointNum then
    --     if isNull(model) then return end

    --     -- 更新点击事件
    --     local BtnExchange = model.transform:Find("BtnExchange")
    --     if not isNull(BtnExchange) then
    --         SetButtonAction(BtnExchange , function()
    --             if self.controller.Argument.parameters then
    --                 self.controller.Argument.parameters.jumpIndex = self._selectIndex
    --             end
    --             local ActivityConstants = import("Game.Activity.ActivityConstants")
    --             StoreUtils.OpenVarietyStore(
    --                     StoreConstants.OpenIds.PointNum,
    --                     {
    --                         { id = Constants.UITypeIds.GachaponEntry },
    --                     },
    --                     {activityUuid = activityData.activityUuid, activityType = ActivityConstants.ActivityType.PointNumShop}
    --             )
    --         end)
    --     end
    --     ---@type UnityEngine.UI.Image
    --     local ImgIcon = BtnExchange.transform:Find("ImgIcon")
    --     local getGachaponConf = GachaponUtils.GetGachaponById(pool.poolId)
    --     if not isNull(ImgIcon) then
    --         local img = ImgIcon.gameObject:GetComponent(typeof(ImageComp))
    --         local path = GoodsConfMgr:GetInstance():GetPhotoPathById(getGachaponConf.singleCoin)
    --         GachaponShared:LoadSpriteAsync(img, path)
    --     end
    --     ---@type UnityEngine.UI.Image
    --     local Text2 = BtnExchange.transform:Find("Text2")
    --     if not isNull(Text2) then
    --         local text2 = Text2.gameObject:GetComponent(typeof(TMPTextComp))
    --         text2.text = tostring(GoodsUtils.GetThingNo(getGachaponConf.singleCoin))
    --     end

    -------------------------------------------------
    -- 海外-阵营卡池
    elseif GachaponUtils.IsOverseaCampType(pool.poolType) then
        if isNull(model) then return end

        -- init data
        ---@type integer[]
        local campIdList   = checkTable(activityData.choosenCamps)
        ---@type string[]
        local poolNameList = checkTable(activityData.campsPoolName)

        ---@type UnityEngine.RectTransform[]
        local tabBtnList  = {}
        ---@type UnityEngine.RectTransform[]
        local bgCellList  = {}
        local selectIndex = 0

        local tabBtnClick = function(campIndex)
            if selectIndex == campIndex and campIndex ~= 0 then return end
            local oldCampTabBtn = tabBtnList[selectIndex]
            local oldCampBgCell = bgCellList[selectIndex]
            local newCampTabBtn = tabBtnList[campIndex]
            local newCampBgCell = bgCellList[campIndex]
            if oldCampTabBtn then
                CfUtils.SetUISwitchImage(oldCampTabBtn:Find('ImgTab'), 1)  -- 1 : cancel
                CfUtils.SetUISwitchText(oldCampTabBtn:Find('TextNumber'), 1)
                CfUtils.SetUISwitchText(oldCampTabBtn:Find('TextDesc'), 1)
            end
            if newCampTabBtn then
                CfUtils.SetUISwitchImage(newCampTabBtn:Find('ImgTab'), 2)  -- 2 : select
                CfUtils.SetUISwitchText(newCampTabBtn:Find('TextNumber'), 2)
                CfUtils.SetUISwitchText(newCampTabBtn:Find('TextDesc'), 2)
            end
            if oldCampBgCell then
                CfUtils.SetActive(oldCampBgCell, false)
            end
            if newCampBgCell then
                CfUtils.SetActive(newCampBgCell, true)
                local animSuffix = string.format('%d_%d', tostring(pool.resource), campIndex)
                --首次进入 Gachapon%d_Enter  第二次播放 Gachapon%d_Again
                if self._isSelectFirst then
                    CfUtils.PlayAnimator(newCampBgCell, string.format("Gachapon%s_Again", animSuffix))
                else
