    -------------------------------------------------
    -- 海外-自选卡池
    elseif pool.poolType == GachaponConstants.PoolType.OverseaOptional then
        if isNull(model) then return end
        
        -- init data
        local cardIdList = checkTable(activityData.choosenCards)
        local CARD_COUNT = 5  -- 选中的卡牌数量
        local NEED_COUNT = 5  -- 一次性选择的数量

        -- 将所有预览卡牌 转换为可用的 fakeCardDojo
        ---@type CardDojo
        local cardDojoList = {}
        ---@param previewDojo GachaponPreviewDojo
        for cardIndex, previewDojo in ipairs(pool.preview) do
            local cardVo = cardConfMgr:GetCardByRefId(previewDojo.itemId)
            if not isNull(cardVo) then
                local fakeCardDojo = CardUtils.GenerateCustomById(previewDojo.itemId)
                table.insert(cardDojoList, fakeCardDojo)
            end
        end

        ---@type table<string, CardDojo>
        local cardDojoMap = {}
        for _, cardDojo in ipairs(cardDojoList) do
            cardDojoMap[tostring(cardDojo.cardId)] = cardDojo
        end

        ---@type UnityEngine.Transform[]
        local cardHeadList = {}
        ---@type UnityEngine.Transform[]
        local cardEmptyList = {}
        
        local updateAllCardNode = function()
            for cardIndex, cardHeadTras in ipairs(cardHeadList) do
                local cardId    = checkInt(cardIdList[cardIndex])
                local cardDojo  = cardDojoMap[tostring(cardId)]
                local emptyNode = cardEmptyList[cardIndex]
                if cardDojo then
                    ---@type CardHeadNode
                    local cardHeadEnv = CfUtils.GetLuaScr(cardHeadTras, Constants.UIBattlingLuaTablePath.CardHeadNode)
                    cardHeadEnv:FreshNode(cardDojo, false, cardIndex)
                    cardHeadEnv:SetRookieStatus(true)
                end
                CfUtils.SetActive(cardHeadTras, cardDojo)
                CfUtils.SetActive(emptyNode, not cardDojo)
            end
        end

        local updateFrameState = function(isAllClose)
            local isSelected = #cardIdList > 0
            if isNull(model) then return end
            CfUtils.SetActive(model.transform:Find('Content/ChangeOptionalCard/BgNode/ImgFrame2'), not isAllClose and isSelected)
            CfUtils.SetActive(model.transform:Find('Content/ChangeOptionalCard/BgNode/ImgFrame1'), not isAllClose and not isSelected)
        end

        local openSelectCardView = function()
            -- 关闭frame
            -- updateFrameState(true)
            CfUtils.DialogOpen(Constants.UITypeIds.UIFightTeamCardChoose, {
                chooseCardStatu = Constants.ChooseCardStatus.Custom,
                customCardDojos = cardDojoList,
                customSelectIds = cardIdList,
                customLeastNum  = NEED_COUNT,
                customLimitNum  = NEED_COUNT,
                ---@param newSelectIds string[]
                confirmCb = function(newSelectIds)
                    local originIds = cardIdList
                    local selectIds = checkTable(newSelectIds)
                    local isChanged = false
                    if #selectIds == #originIds then
                        for cardIndex, cardId in ipairs(originIds) do
                            if checkInt(selectIds[cardIndex]) ~= checkInt(cardId) then
                                isChanged = true
                                break
                            end
                        end
                    else
                        isChanged = true
                    end
                    if isChanged then
                        local gachaponPoolId = checkInt(pool.poolId)
                        local activityData   = checkTable(pool.activity)
                        local activityUuid   = checkInt(activityData.activityUuid)
                        local cardsString    = table.concat(selectIds, ',')
                        local requestData    = {
                            poolId       = gachaponPoolId,
                            activityUuid = activityUuid,
                            cards        = cardsString
                        }
                        -- request choose cards
                        GameUtils.Request(Interfaces.CALL_OVERSEA_CHOOSE_CARDS, requestData, function(request, response)
                            if checkNumber(response.errCode) == 0 then
                                -- cardIdList = selectIds
                                -- activityData.choosenCards = selectIds
                                -- updateAllCardNode()
                                -- updateFrameState()
                                -- self:RefreshLayout(pool)
                                -- self:RefreshBtnInfo()
                                GameUtils.Toast(localize('设定成功'))
                            end
                        end)
                    end
                end,
                -- closeCb = function()
                --     updateFrameState()
                -- end
            }, {UIArgs(Constants.UITypeIds.GachaponEntry)})
        end

        local teamParentNode = model and model.transform:Find('Content/ChangeOptionalCard/BtnTeamMember') or nil
        if isNotNull(teamParentNode) then
            for cardIndex = 1, CARD_COUNT do
                local cardAreaTras  = teamParentNode:Find(string.format('BtnMemberNode%d/Area', cardIndex))
                local cardEmptyTras = teamParentNode:Find(string.format('BtnMemberNode%d/Empty', cardIndex))
                local cardHeadTras  = teamParentNode:Find(string.format('BtnMemberNode%d/CommonSmallHeadNode', cardIndex))
