            updateAllCardNode()
        end
        updateFrameState()

    -------------------------------------------------
    -- 海外-自选UP卡池
    elseif GachaponUtils.IsOverseaOptionalUpType(pool.poolType) then
        if isNull(model) then return end
        
        -- init data
        local choosenCardId = checkInt(activityData.choosenCardId)
        local cardIdList    = {}
        local CARD_COUNT    = 1  -- 选中的卡牌数量
        local NEED_COUNT    = 1  -- 一次性选择的数量
        if choosenCardId > 0 then
            table.insert(cardIdList, choosenCardId)
        end

        -- 将所有预览卡牌 转换为可用的 fakeCardDojo
        ---@type CardDojo
        local cardDojoList = {}
        for cardIndex, cardId in ipairs(checkTable(activityData.optionalIdList)) do
            local cardVo = cardConfMgr:GetCardByRefId(cardId)
            if not isNull(cardVo) then
                local fakeCardDojo = CardUtils.GenerateCustomById(cardId)
                table.insert(cardDojoList, fakeCardDojo)
            end
        end

        ---@type table<string, CardDojo>
        local cardDojoMap = {}
        for _, cardDojo in ipairs(cardDojoList) do
            cardDojoMap[tostring(cardDojo.cardId)] = cardDojo
        end

        SetButtonAction(model.transform:Find('Content/BtnChoose'), function()
            CfUtils.DialogOpen(Constants.UITypeIds.UIFightTeamCardChoose, {
                chooseCardStatu = Constants.ChooseCardStatus.Custom,
                customCardDojos = cardDojoList,
                customSelectIds = cardIdList,
                customLeastNum  = NEED_COUNT,
                customLimitNum  = NEED_COUNT,
                ---@param newSelectIds string[]
                confirmCb = function(newSelectIds)
                    local originIds = cardIdList
                    local selectIds = checkTable(newSelectIds)
                    local isChanged = false
                    if #selectIds == #originIds then
                        for cardIndex, cardId in ipairs(originIds) do
                            if checkInt(selectIds[cardIndex]) ~= checkInt(cardId) then
                                isChanged = true
                                break
                            end
                        end
                    else
                        isChanged = true
                    end
                    if isChanged then
                        local gachaponPoolId = checkInt(pool.poolId)
                        local activityData   = checkTable(pool.activity)
                        local activityUuid   = checkInt(activityData.activityUuid)
                        local cardsString    = table.concat(selectIds, ',')
                        local requestData    = {
                            poolId       = gachaponPoolId,
                            activityUuid = activityUuid,
                            cardId       = cardsString
                        }
                        -- request choose cards
                        GameUtils.Request(Interfaces.CALL_OVERSEA_CHOOSE_UP_CARD, requestData, function(request, response)
                            if checkNumber(response.errCode) == 0 then
                                GameUtils.Toast(localize('设定成功'))
                            end
                        end)
                    end
                end,
            }, {UIArgs(Constants.UITypeIds.GachaponEntry)})
        end)

        SetButtonAction(model.transform:Find('Content/BtnPT'), function()
            GachaponShared.RecordJump = self._selectIndex
            local gachaponPoolId    = checkInt(pool.poolId)
            local activityData      = checkTable(pool.activity)
            local ActivityConstants = import("Game.Activity.ActivityConstants")
            CfUtils.DialogOpen(Constants.UITypeIds.UIActivityCommonShopDialog, {
                mallBgImage  = 'Arts/Textures/UIBg/draw_celebration_shop_bg.png',
                activityUuid = checkInt(activityData.activityUuid),
                customType   = ActivityConstants.ActivityType.GachaponChoosenUp,
                topGoods     = { checkInt(activityData.choosenCornId) },
            }, {UIArgs(Constants.UITypeIds.GachaponEntry)})
        end)

        CfUtils.SetActive(model.transform:Find('Content/BtnPT/redPoint'), self:CheckPoolHasChoosenMallRed(pool))

        local updateFrameState = function()
            local isChoosenCard = choosenCardId > 0
            CfUtils.SetUISwitchImage(model.transform:Find('Content/BtnChoose/Root/ImgBG'), isChoosenCard and 2 or 1)
            -- CfUtils.SetActive(model.transform:Find('Content/BtnChoose/Root/UIFX_Frame'), not isChoosenCard)
            CfUtils.SetActive(model.transform:Find('Content/BtnChoose/Root/ImgAdd'), not isChoosenCard)
            CfUtils.SetActive(model.transform:Find('Content/BtnChoose/Root/HeadGroup'), isChoosenCard)
            if isChoosenCard then
                local cardVo = cardConfMgr:GetCardByRefId(choosenCardId)
                local skinVo = cardConfMgr:GetCardSkinBySkinId(cardVo.defaultSkin)
                CfUtils.FillImage(model.transform:Find('Content/BtnChoose/Root/HeadGroup/ImgHeadIcon'), skinVo.buffHead)
            end
        end
        updateFrameState()

    -------------------------------------------------
    -- 海外-光暗卡池
    elseif GachaponUtils.IsOverseaLightDarkType(pool.poolType) then
        if isNull(model) then return end

        local cardExchangeNum = checkInt(activityData.cardExchangeNum)
        local coinGoodsIcon   = GoodsConfMgr:GetInstance():GetPhotoPathById(Constants.Currency.LightDarkCoin)
        CfUtils.FillText(model.transform:Find('Content/BtnExchange/ExchangeDesc/TextNumber'), cardExchangeNum)
        CfUtils.FillImage(model.transform:Find('Content/BtnExchange/ExchangeDesc/ImgGoodsIcon'), coinGoodsIcon)

        SetButtonAction(model.transform:Find('Content/BtnExchange'), function()
            GachaponShared.RecordJump = self._selectIndex
            local ids = {{id = Constants.UITypeIds.GachaponEntry}}
            local GroceryUtils = import('Game.Grocery.GroceryUtils')
            GroceryUtils.OpenGroceryStore(GroceryConstants.GroceryType.LightDark, ids)
        end)

    -------------------------------------------------
    elseif GachaponUtils.IsOverseaStepType(pool.poolType) then
        CfUtils.SetActive(self.BtnOneNode.gameObject, false)
        CfUtils.SetActive(self.BtnTen.gameObject, false)
        CfUtils.SetActive(self.TxtTime.transform.parent, false)
        local env = CfUtils.GetLuaScr(model,"Game.Gachapon.GachaponStepDiscountEntry")
        if not isNull(env) then
            env:SetCallBack(Bind(self,self.OnBtnDrawStepClick))
            env:RefreshShow(pool)
        end
    elseif GachaponUtils.IsOverseaCoronaType(pool.poolType) then
        CfUtils.SetActive(self.BtnOneNode.gameObject, false)
        CfUtils.SetActive(self.BtnTen.gameObject, false)
        CfUtils.SetActive(self.TxtTime.transform.parent, false)
        local env = CfUtils.GetLuaScr(model,"Game.Gachapon.GachaponStepNode")
        if not isNull(env) then
            env:SetCallBack(Bind(self,self.OnBtnDrawStepClick))
            local extra = isNotNull(self.controller.Argument) and self.controller.Argument.extra or nil
            env:RefreshShow(pool, extra)
        end
    end

    -------------------------------------------------------------------------------
    -- 卡池的进度奖励
    -------------------------------------------------------------------------------
    local nameMaskNode = model and model.transform:Find('Content/NameMask') or nil
    if #checkTable(activityData.overseaActivityInfo) > 0 then
        CfUtils.SetActive(self.ActivityRewardNode, true)
        if isNotNull(nameMaskNode) then
            nameMaskNode.anchoredPosition = Vector2(nameMaskNode.anchoredPosition.x, 524)
        end

        local progressTimes = 0
        local drawnTimesMap = {}
        for _, drawnTimes in ipairs(checkTable(activityData.overseaActivityReceived)) do
            drawnTimesMap[tostring(drawnTimes)] = true
        end

        local allProgressInfos  = checkTable(activityData.overseaActivityInfo)
        local lastProgressInfo  = checkTable(allProgressInfos[#allProgressInfos])
        local lastProgressTimes = checkInt(lastProgressInfo.times)

        ---@type UnityEngine.RectTransform
        local nodeParentRT   = self.ActivityRewardNode:Find('Reward'):GetComponent(typeof(RectTransform))
        local progressText   = self.ActivityRewardNode:Find('Progress/Layout/TextNumber'):GetComponent(typeof(TMPTextComp))
        local progressSlider = self.ActivityRewardNode:Find('Slider'):GetComponent(typeof(SliderComp))
        
        ---@type GachaponProgressRewardNode[]
        local rewardNodeList = {}

        -- local NODE_ANCHOR_LIST    = { 0.124, 0.251, 0.398, 0.55, 0.747, 1 }
        local progressNodeAnchors = {}
        local updateProgressTimes = function(newProgressTimes)
            progressTimes = checkInt(newProgressTimes)
            -- 更新当前抽卡次数
            CfUtils.FillText(progressText, tostring(progressTimes))
            -- 更新进度条进度
            local progressIndex = #allProgressInfos
            for index, progressInfo in ipairs(allProgressInfos) do
                -- progressNodeAnchors[index] = NODE_ANCHOR_LIST[checkInt(progressInfo.level)]
                progressNodeAnchors[index] = checkInt(progressInfo.level) * 0.1
                if progressTimes <= checkInt(progressInfo.times) then
                    progressIndex = index
                    break
                end
            end
            local baseProgressCount     = checkInt(checkTable(allProgressInfos[progressIndex -1]).times)
            local nextProgressCount     = checkInt(checkTable(allProgressInfos[progressIndex]).times)
            local progressCountPercent  = (progressTimes - baseProgressCount) / (nextProgressCount - baseProgressCount)
            local baseProgressPercent   = checkNumber(progressNodeAnchors[progressIndex - 1])
            local nextProgressPercent   = checkNumber(progressNodeAnchors[progressIndex])
            local targetprogressPercent = baseProgressPercent + (nextProgressPercent - baseProgressPercent) * progressCountPercent
            CfUtils.SetSliderPercent(progressSlider, math.max(0, math.min(targetprogressPercent, 1)))
            -- 刷新全部节点领取状态
            for nodeIndex, rewardNode in ipairs(rewardNodeList) do
                local nodeRewardData = checkTable(allProgressInfos[nodeIndex])
                local nodeDrawState  = Constants.GetStatus.Not
                if drawnTimesMap[tostring(nodeRewardData.times)] then
                    nodeDrawState = Constants.GetStatus.Has
                elseif progressTimes >= checkInt(nodeRewardData.times) then
                    nodeDrawState = Constants.GetStatus.Can
                end
                rewardNode:SetNodeDrawState(nodeDrawState)
            end
        end
        updateProgressTimes(activityData.overseaActivityCallTimes)

        ---@param sender GachaponProgressRewardNode
        local drawNodeClickCB = function(sender)
            -- 是否可领取
            if sender:GetNodeDrawState() == Constants.GetStatus.Can then
                -- request choose cards
                local requestData = {
                    poolId       = pool.poolId,
                    activityUuid = activityData.activityUuid,
                    times        = sender:GetRewardDrawTimes(),
                }
                local drawInterface = checkInt(requestData.activityUuid) > 0 and Interfaces.CALL_OVERSEA_ACTIVITY_DRAW or Interfaces.CALL_OVERSEA_ACCOUNT_DRAW
                GameUtils.Request(drawInterface, requestData, function(request, response)
                    if checkNumber(response.errCode) == 0 then
                        local responseData = checkTable(response.data)
                        -- 更新缓存数据：记录领取
                        table.insert(activityData.overseaActivityReceived, sender:GetRewardDrawTimes())
                        -- 记录已领取的次数
                        drawnTimesMap[tostring(sender:GetRewardDrawTimes())] = true
                        -- 刷新节点领取状态
                        sender:SetNodeDrawState(Constants.GetStatus.Has)
                        -- 领取奖励
                        local rewardList = checkTable(responseData.rewards)
                        GoodsUtils.DrawRewards(rewardList)
                        CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, {rewards = rewardList})
                        -- 检测是否重置次数（可反复领取）
                        local newProgressTimes = checkInt(responseData.callTimes)
                        if progressTimes ~= newProgressTimes then
                            -- 更新缓存数据：重置抽卡次数
                            activityData.overseaActivityCallTimes = newProgressTimes
                            -- 更新缓存数据：清空领取记录
                            activityData.overseaActivityReceived = {}
                            -- 清空已领取次数记录
                            drawnTimesMap = {}
                            -- 更新剩余抽取次数
                            updateProgressTimes(newProgressTimes)
                        end
                        -- update poolCell redPoint
                        self:UpdatePoolsListRedPoint(pool.poolId)
                        self:RefreshRedPoint()
                    end
                end)
            elseif sender:GetNodeDrawState() == Constants.GetStatus.Has then
                GameUtils.Toast(localize('奖励已领取'))
            else
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(sender:GetRewardGoodsId())
                GameUtils.ShowCommonTipsBoard(sender.controller, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
            end
        end

        
        local rewardNodeRt  = nil
        local rewardInfoMap = {}
        for _, nodeRewardData in ipairs(allProgressInfos) do
            rewardInfoMap[tostring(nodeRewardData.level)] = nodeRewardData
        end
        for nodeIndex = 1, nodeParentRT.childCount do
            rewardNodeRt = nodeParentRT:Find('GachaponRewardNode' .. nodeIndex)
            -- 多余的隐藏
            local nodeRewardData = rewardInfoMap[tostring(nodeIndex)]
            if nodeRewardData then
                CfUtils.SetActive(rewardNodeRt, true)
                ---@type GachaponProgressRewardNode
                local rewardNodeEnv = CfUtils.GetLuaScr(rewardNodeRt, 'Game.Gachapon.GachaponProgressRewardNode')
                local nodeDrawState = Constants.GetStatus.Not
                if drawnTimesMap[tostring(nodeRewardData.times)] then
                    nodeDrawState = Constants.GetStatus.Has
                elseif progressTimes >= checkInt(nodeRewardData.times) then
                    nodeDrawState = Constants.GetStatus.Can
                end
                if not isNull(rewardNodeEnv) then
                    rewardNodeEnv:RefreshData(nodeIndex, nodeRewardData)
                    rewardNodeEnv:SetNodeDrawState(nodeDrawState)
                    rewardNodeEnv:SetClickNodeCB(drawNodeClickCB)
                    table.insert(rewardNodeList, rewardNodeEnv)
                end
            else
                CfUtils.SetActive(rewardNodeRt, false)
            end
        end
    else
        CfUtils.SetActive(self.ActivityRewardNode, false)
        if GachaponUtils.IsOverseaOptionalUpType(pool.poolType) then
            -- 不要干涉名字节点的位置
        else
            if isNotNull(nameMaskNode) then
                nameMaskNode.anchoredPosition = Vector2(nameMaskNode.anchoredPosition.x, 337)
            end
        end
    end

    -------------------------------------------------------------------------------
    -- 卡池的宣传视频
    -------------------------------------------------------------------------------
    if not string.isEmpty(pool.video) then
        self:PoolVideoPlay_(pool.video)
    else
        -- self:PoolVideoPlay_('gachapon_open_door2')
        self:PoolVideoStop_()
    end

end

function GachaponEntry:RefreshRedPoint()
    ---@type RedPointMgrComponent
    local redPointCom = GameUtils.GetEntityCompByType(ECSComponentType.Constants.RedPointMgrComponent)

    local hasDrawRewardsRed = false
    for poolIndex, pool in ipairs(self.AllGachapon) do
        hasDrawRewardsRed = self:CheckPoolHasDrawRewardsRed(pool)
        if hasDrawRewardsRed then
            break
        end
    end
    redPointCom:SetNodeNum(Constants.RedPointConst.GachaponProgressRewards, hasDrawRewardsRed and 1 or 0)

    local hasChoosenMallRed = false
    for poolIndex, pool in ipairs(self.AllGachapon) do
        hasChoosenMallRed = self:CheckPoolHasChoosenMallRed(pool)
        if hasChoosenMallRed then
            break
        end
    end
    redPointCom:SetNodeNum(Constants.RedPointConst.GachaponChoosenMall, hasChoosenMallRed and 1 or 0)

    local hasActivityTaskRed = false
    for poolIndex, pool in ipairs(self.AllGachapon) do
        hasActivityTaskRed = self:CheckPoolHasActivityTaskRed(pool)
        if hasActivityTaskRed then
            break
        end
    end
    redPointCom:SetNodeNum(Constants.RedPointConst.GachaponActivityTask, hasActivityTaskRed and 1 or 0)
end

---@param pool GachaponDojo
---@return boolean
function GachaponEntry:CheckPoolHasDrawRewardsRed(pool)
    local hasDrawRewardsRed = false
    local poolActivityData  = checkTable(checkTable(pool).activity)
    local allProgressInfos  = checkTable(poolActivityData.overseaActivityInfo)
    if #allProgressInfos > 0 then
        local receivedTimesMap  = {}
        local activityCallTimes = checkInt(poolActivityData.overseaActivityCallTimes)
        for _, receivedTimes in ipairs(checkTable(poolActivityData.overseaActivityReceived)) do
            receivedTimesMap[tostring(receivedTimes)] = true
        end
        for _, nodeRewardData in ipairs(allProgressInfos) do
            if activityCallTimes >= checkInt(nodeRewardData.times) and not receivedTimesMap[tostring(nodeRewardData.times)] then
                hasDrawRewardsRed = true
                break
            end
        end
    end
    return hasDrawRewardsRed
end

---@param pool GachaponDojo
---@return boolean
function GachaponEntry:CheckPoolHasChoosenMallRed(pool)
    local hasChoosenMallRed = false
    local poolActivityData  = checkTable(checkTable(pool).activity)
    if poolActivityData.choosenRedTips ~= nil and checkInt(poolActivityData.choosenRedTips) >= 0 then
        hasChoosenMallRed = true
    end
    return hasChoosenMallRed
end

---@param pool GachaponDojo
---@return boolean
function GachaponEntry:CheckPoolHasActivityTaskRed(pool)
    local hasActivityTaskRed = false
    local poolActivityData  = checkTable(checkTable(pool).activity)
    if poolActivityData.taskRedTips ~= nil and checkInt(poolActivityData.taskRedTips) >= 0 then
        hasActivityTaskRed = true
    end
    return hasActivityTaskRed
end

--- 刷新卡池入口列表（process-1）
function GachaponEntry:InitPoolsList()
    local cnt = #self.AllGachapon
    CfUtils.SetActive(self.itemCell,false)
    GachaponUtils.ResizeContent(self.Content,cnt,self.itemCell)
    for i = 1, cnt do
        self.Content:GetChild(i - 1).gameObject.name = "Cell"..i
        CfUtils.SetActive(self.Content:GetChild(i - 1).transform:Find("ImaLine").gameObject, i ~= cnt)
        local itemIns = self.Content:GetChild(i - 1).transform:Find("BtnNode").gameObject
        ---@type GachaponDojo
        local pool = self.AllGachapon[i]
        local resourceId = pool.resource or pool.poolId
        SetButtonAction(itemIns:GetComponent(typeof(ButtonComp)), function()
            self._isSelectFirst = true
            self:OnSelectButton(i - 1)
        end)

        local TextNumber = itemIns.transform:Find("TextNumber").gameObject:GetComponent(typeof(TMPTextComp))
        TextNumber.text = string.format("%02d", i)
        if not isNull(resourceId) then
            if pool.poolType == GachaponConstants.PoolType.OverseaStepSingle then
                local notSelectImg = itemIns.transform:Find("ImgBannerNotSelect").gameObject:GetComponent(typeof(RawImageComp))
                GachaponUtils.LoadSpriteAsync(notSelectImg, string.format(GachaponConstants.EntryResPath,resourceId, pool.btnType))
                local seletImg = itemIns.transform:Find("ImgBannerSelect").gameObject:GetComponent(typeof(RawImageComp))
                GachaponUtils.LoadSpriteAsync(seletImg, string.format(GachaponConstants.EntryResPath,resourceId,"draw_tab_2"))
            else
                local notSelectImg = itemIns.transform:Find("ImgBannerNotSelect").gameObject:GetComponent(typeof(RawImageComp))
                GachaponUtils.LoadSpriteAsync(notSelectImg, string.format(GachaponConstants.EntryResPath,resourceId,"draw_tab_1"))
                local seletImg = itemIns.transform:Find("ImgBannerSelect").gameObject:GetComponent(typeof(RawImageComp))
                GachaponUtils.LoadSpriteAsync(seletImg, string.format(GachaponConstants.EntryResPath,resourceId,"draw_tab_2"))
            end
            
        end
        CfUtils.SetActive(itemIns.transform:Find("ImgBannerSelect"),false)
        CfUtils.SetActive(itemIns.transform:Find("ImgShadow"),false)
        CfUtils.SetActive(itemIns.transform:Find("ImgFukubukuro"), next(pool.luckBagActivityData) ~= nil)

        if SPECIAL_POOLS[tostring(pool.poolId)] then
            local nameWhite = itemIns.transform:Find("NameWhite")
            if not isNull(nameWhite) then
                local nameWhiteText =  nameWhite.transform:GetComponent(typeof(TextComp))
                nameWhiteText.text = pool.poolName
                CfUtils.SetActive(nameWhite , true)
                CfUtils.SetActive(itemIns.transform:Find("Name") , false)
            else
                local nameText =  itemIns.transform:Find("Name").transform:GetComponent(typeof(TextComp))
                nameText.text = pool.poolName
                CfUtils.SetActive(itemIns.transform:Find("nameWhiteText") , false)
                CfUtils.SetActive(itemIns.transform:Find("Name") , true)
            end
        else
            local nameNode  = itemIns.transform:Find("Name")
            local nameWhite = itemIns.transform:Find("NameWhite")
            CfUtils.FillText(nameNode, pool.poolName)
            CfUtils.FillText(nameWhite, pool.poolName)
            if GachaponUtils.IsOverseaPoolNameWhite(pool.poolType) then
                CfUtils.SetActive(nameWhite, true)
                CfUtils.SetActive(nameNode, false)
            else
                CfUtils.SetActive(nameWhite, false)
                CfUtils.SetActive(nameNode, true)
            end
        end

        -- 边框发光特效效果
        CfUtils.SetActive(itemIns.transform:Find("UIFX_SpecialEffect"), GachaponUtils.IsShowCellSpecialEffect(pool.poolType))

        -- 特殊专属效果
        local showSpecialDefine = {
            [GachaponConstants.PoolType.OverseaAccount]    = 1,
            [GachaponConstants.PoolType.OverseaOptionalUp] = 2,
        }
        local showSpecialState = checkInt(showSpecialDefine[checkInt(pool.poolType)])
        CfUtils.SetActive(itemIns.transform:Find("BeginnerSymbol"), showSpecialState > 0)
        if showSpecialState > 0 then
            CfUtils.SetUISwitchImage(itemIns.transform:Find("BeginnerSymbol/ImgBg"), showSpecialState)
            CfUtils.SetUISwitchText(itemIns.transform:Find("BeginnerSymbol/TextDesc"), showSpecialState)
        end

        local isShowTimeInfo = GachaponUtils.IsShowTimeInfoType(pool.poolType) and (pool:IsValidActivity() or pool.remainSeconds > -1)
        CfUtils.SetActive(itemIns.transform:Find("Timer"), isShowTimeInfo)

        ---@type  Game.Native.Common.UISwitchImage
        local imageBg = itemIns.transform:Find("Timer/ImgBg").gameObject:GetComponent(typeof(UISwitchImage))
        imageBg.Status = 1
        if isShowTimeInfo then
            local timerText = itemIns.transform:Find("Timer/Text").gameObject:GetComponent(typeof(TextComp))

            if not isNull(self._timeDown[pool.poolId]) then
                CDTimerModule.GetInstance():RemoveCD(self._timeDown[pool.poolId])
                self._timeDown[pool.poolId] = nil
            end

            if (pool:IsValidActivity() and checkInt(pool.activity.endRemainTime) <= 0) or (pool.remainSeconds == 0) then
                CfUtils.FillText(timerText, localize("已结束"))
                local TxtCloseTime = self.TxtTime.transform:Find("TxtCloseTime")
                if pool:IsValidActivity() then
                    CfUtils.SetActive(TxtCloseTime, true)
                    CfUtils.FillText(self.TxtTime, os.date("%Y.%m.%d", pool.activity.closeTime))
                else
                    CfUtils.SetActive(TxtCloseTime, false)
                    CfUtils.FillText(self.TxtTime, '')
                end
                imageBg.Status = 2
            else
                self._timeDown[pool.poolId] = CDTimerModule.GetInstance():AddCD(1, function(count, id)
                    if (pool:IsValidActivity() or pool.remainSeconds ~= -1) then
                        if count <= 0 then
                            CfUtils.FillText(timerText, localize("已结束"))
                            local TxtCloseTime = self.TxtTime.transform:Find("TxtCloseTime")
                            if pool:IsValidActivity() then
                                CfUtils.SetActive(TxtCloseTime, true)
                                CfUtils.FillText(self.TxtTime, os.date("%Y.%m.%d", pool.activity.closeTime))
                            else
                                CfUtils.SetActive(TxtCloseTime, false)
                                CfUtils.FillText(self.TxtTime, '')
                            end
                            imageBg.Status = 2
                            -- 活动结束等待UI确认
                            return
                        end
                        local day = tonumber(math.floor(count/86400))
                        local timer = ""
                        if day > 0 then
                            timer = localize("剩余_num_天", {_num_ = day})
                        else
                            timer = CfUtils.GetTimeHMS9(count)
                        end
                        if pool:IsValidActivity() then
                            pool.activity.endRemainTime = count
                        else
                            pool.remainSeconds = count
                        end
                        CfUtils.FillText(timerText, timer)
                    end
                end, pool:IsValidActivity() and pool.activity.endRemainTime or pool.remainSeconds, true, true)
            end
        end

        -- update poolCell redPoint
        self:UpdatePoolsListRedPoint(pool.poolId)
    end

    local initParams = CfUtils.DialogSafeParameters(self.controller)
    if initParams.contentPosY then
        self.Content.anchoredPosition = Vector3(
            self.Content.anchoredPosition.x, 
            initParams.contentPosY,
            self.Content.anchoredPosition.z
        )
    end
end
function GachaponEntry:UpdatePoolsListRedPoint(poolId)
    for poolIndex, pool in ipairs(self.AllGachapon) do
        if checkInt(pool.poolId) == checkInt(poolId) then
            local itemIns = self.Content:GetChild(poolIndex - 1).transform:Find("BtnNode").gameObject
            if itemIns then
                local hasDrawRewardsRed   = self:CheckPoolHasDrawRewardsRed(pool)
                local hasChoosenMallRed   = self:CheckPoolHasChoosenMallRed(pool)
                local hasActivityTaskRed  = self:CheckPoolHasActivityTaskRed(pool)
                local hasConsumeEnoughRed = GachaponUtils.CheckConsumeEnoughRedPointBy(pool.poolId)
                local hasFreeCallRed      = GachaponUtils.CheckFreeCallRedPointBy(pool.poolId)
                local hasFeedBackRed      = self:CheckPoolHasFeedBackTaskRed(pool)
                CfUtils.SetActive(itemIns.transform:Find("redPoint"), hasFreeCallRed or hasDrawRewardsRed or hasConsumeEnoughRed or hasChoosenMallRed or hasActivityTaskRed or hasFeedBackRed)
            end
            break
        end
    end
end

function GachaponEntry:AddListener()
    self._itemChangeHandler = Events.AddListener(StoreConstants.StoreEvents.OnFragsRefresh, Bind(self, self.RefreshRedPoint))
    self.eventFreeTimesCountdown_ = Events.AddListener(Constants.EventNames.GACHAPON_FREE_TIMES_COUNTDOWN, Bind(self, self.OnCFreeTimesCountdownHandler_))
    self.eventCommonMainlineTaskTipsNode_ = Events.AddListener(Constants.EventNames.UICommonMainlineTaskTipsNodeEventName, Bind(self, self.OnCommonMainlineTaskTipsNodeHandler_))
    GameUtils.BindRedPoint(Constants.RedPointConst.GachaponHasFreeCall, self.Content, false, nil, function()
        for _, pool in ipairs(self.AllGachapon) do
            self:UpdatePoolsListRedPoint(pool.poolId)
        end
    end)
end

function GachaponEntry:RemoveListener()
    if self._itemChangeHandler ~= nil then
        Events.RemoveListener(StoreConstants.StoreEvents.OnFragsRefresh, self._itemChangeHandler)
        self._itemChangeHandler = nil
    end
    if self.eventFreeTimesCountdown_ ~= nil then
        Events.RemoveListener(Constants.EventNames.GACHAPON_FREE_TIMES_COUNTDOWN, self.eventFreeTimesCountdown_)
        self.eventFreeTimesCountdown_ = nil
    end
    if self.eventCommonMainlineTaskTipsNode_ ~= nil then
        Events.RemoveListener(Constants.EventNames.UICommonMainlineTaskTipsNodeEventName, self.eventCommonMainlineTaskTipsNode_)
        self.eventCommonMainlineTaskTipsNode_ = nil
    end
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.GachaponHasFreeCall)
end

