-- 刷新界面中的控制按钮
function GachaponEntry:RefreshBtnInfo()
    CfUtils.SetActive(self.BtnOneNode, true)
    
    ---@type GachaponDojo
    local pool = self.AllGachapon[self._selectIndex + 1]
    self:RefreshLayout(pool)

    local isShowFeedBack = isSet(pool,"feedbackTasks") and (table.count(pool.feedbackTasks) > 0)
    CfUtils.SetActive(self.BtnFeedback.gameObject, isShowFeedBack)
    if isShowFeedBack then
        SetButtonAction(self.BtnFeedback, function()
            self:OnBtnFeedbackClick(pool)
        end)

        local hasFeedBackRed = self:CheckPoolHasFeedBackTaskRed(pool)
        local redGo = GameUtils.GetRedPointGo(self.BtnFeedback)
        CfUtils.SetActive(redGo,hasFeedBackRed)
    end

    local oneConsume  = checkTable(pool.oneConsume)
    local tenConsume  = checkTable(pool.tenConsume)
    local oneFreeData = nil
    local tenFreeData = nil
    if pool.freeData then
        oneFreeData = {times = pool.freeData.oneLeftTimes, seconds = pool.freeData.oneLeftSeconds}
    end

    local isGuidPoolDrawOne = GachaponUtils.GetGuidPoolDrawType() == GachaponConstants.CallType.One
    local ifDoubleCorn = self:GetDoubleCorn(pool)
    self:UpdateBtnInfo(self.SourceOne.transform, oneFreeData, oneConsume.goodsId, oneConsume.num, true ,ifDoubleCorn)
    self:UpdateBtnInfo(self.SourceTen.transform, tenFreeData, tenConsume.goodsId, tenConsume.num, true ,ifDoubleCorn)
    self:UpdateBtnInfo(self.SourceNew.transform, 
        isGuidPoolDrawOne and oneFreeData or tenFreeData, 
        isGuidPoolDrawOne and oneConsume.goodsId or tenConsume.goodsId, 
        isGuidPoolDrawOne and oneConsume.num or tenConsume.num, 
        true
    )

    local hasOneFreeCallRed = GachaponUtils.CheckFreeCallRedPointBy(pool.poolId, GachaponConstants.CallType.One)
    CfUtils.SetActive(self.RedPointOne, hasOneFreeCallRed)

    local hasTenFreeCallRed   = GachaponUtils.CheckFreeCallRedPointBy(pool.poolId, GachaponConstants.CallType.Ten)
    local hasConsumeEnoughRed = GachaponUtils.CheckConsumeEnoughRedPointBy(pool.poolId)
    CfUtils.SetActive(self.RedPointTen, hasTenFreeCallRed or hasConsumeEnoughRed)
   
    CfUtils.FillText(self.BtnNew.transform:Find('Text'), localize('召唤_num_次', {_num_ = isGuidPoolDrawOne and 1 or 10}))
    SetButtonAction(self.BtnNew, function()
        self:OnGachaponBtn(isGuidPoolDrawOne and GachaponConstants.CallType.One or GachaponConstants.CallType.Ten)
    end)
    SetButtonAction(self.BtnOne, function()
        self:OnGachaponBtn(GachaponConstants.CallType.One)
    end)
    SetButtonAction(self.BtnTen, function()
        self:OnGachaponBtn(GachaponConstants.CallType.Ten)
    end)
   
    if GachaponUtils.IsShowSSRInfoType(pool) then
        if GachaponUtils.IsOverseaStepType(pool.poolType) then
            local text = localize("进行完_num_阶召唤后，本次活动结束",{_num_ = pool.activity.totalStepNum})
            CfUtils.FillText(self.BtnTipsGroup:Find("TxtProbability"), text)
        else
            local getSSRTimes = checkInt(pool.getSSRTimes)
            if GachaponUtils.IsOverseaCampType(pool.poolType) then
                local selectedCampId   = checkInt(self._selectedCampId)
                local campsGetSSRTimes = checkTable(pool.activity.campsGetSSRTimes)
                getSSRTimes = checkInt(campsGetSSRTimes[tostring(selectedCampId)])
            end
            if getSSRTimes <= 0 then
                CfUtils.SetActive(self.BtnTipsGroup, false)
            else
                local text = localize("再召唤<color=#ff48ba><size=32>_num_</size></color>次必得SSR战斗员", {_num_ = getSSRTimes})
                CfUtils.FillText(self.BtnTipsGroup:Find("TxtProbability"), text)

                -- 陈菲说肯定次数和福袋肯定一起显示
                local hasLuckBagActivity = next(pool.luckBagActivityData) ~= nil
                CfUtils.SetActive(self.BtnTipsGroup:Find("BtnFukubukuro"), hasLuckBagActivity)
                if hasLuckBagActivity then
                    local goodsId  = checkInt(pool.luckBagActivityData.luckBagId)
                    local iconPath = GoodsConfMgr:GetInstance():GetPhotoPathById(goodsId)
                    CfUtils.FillImage(self.BtnTipsGroup:Find("BtnFukubukuro/Root/ImgIco"), iconPath)
                    local ActivityUtils = import('Game.Activity.ActivityUtils')
                    local entrancePath  = ActivityUtils.GetImageFullPath(pool.luckBagActivityData.entranceImage)
                    CfUtils.FillImage(self.BtnTipsGroup:Find("BtnFukubukuro/Root/ImgBG"), entrancePath)
                    SetButtonAction(self.BtnTipsGroup:Find("BtnFukubukuro"), function()
                        GachaponShared.RecordJump = self._selectIndex
                        ActivityUtils.OpenActivityView(pool.luckBagActivityData.id, {
                            UIArgs(Constants.UITypeIds.GachaponEntry)
                        })
                    end)
                end
            end
        end
    else
        CfUtils.SetActive(self.BtnTipsGroup,false)
    end
end

function GachaponEntry:GetDoubleCorn(pool)
    if checkInt(pool.ifDoubleCorn) > 0  then
        return pool.ifDoubleCorn
    end
    return 0
end
-- 更新内容区的布局
---@param pool GachaponDojo
function GachaponEntry:RefreshLayout(pool)
    local poolType = pool.poolType
    local lock = pool.isUnlock == 0

    CfUtils.SetActive(self.BtnTen.transform:Find("AnimRoot/Unlock"), not lock)
    -- self.BtnTen.transform.anchoredPosition = Vector2.New(713, -267)

    -- 恢复成默认样式
    CfUtils.SetUISwitchImage(self.BtnOne, 1)
    CfUtils.SetUISwitchImage(self.BtnTen.transform:Find("AnimRoot/Unlock/ImgBg"), 1)
    CfUtils.SetActive(self.BtnNewNode, false)
    CfUtils.SetActive(self.BtnTenUIFX, false)
    CfUtils.SetActive(self.ImgSlogan, GachaponUtils.IsOverseaProgressType(poolType) or GachaponUtils.IsOverseaOptionalUpType(poolType))
    if checkInt(pool.poolId) >= 212001 and checkInt(pool.poolId) <= 212999 then
        CfUtils.SetActive(self.ImgSlogan,false)
    end
    -- 战斗训练按钮
    local hasTrainActivity = next(pool.trainActivityData) ~= nil
    CfUtils.SetActive(self.BtnTrain, hasTrainActivity)
    if hasTrainActivity then
        local isPassed = checkInt(pool.trainActivityData.isPassed) == 1
        CfUtils.SetActive(self.BtnTrain.transform:Find('redPoint'), not isPassed)
        CfUtils.SetActive(self.BtnTrain.transform:Find('UIFX_Unfininshed'), not isPassed)
        CfUtils.SetUISwitchImage(self.BtnTrain.transform:Find('ImgBg'), isPassed and 1 or 2)
    end

    -- 任务按钮
    CfUtils.SetActive(self.BtnTask, GachaponUtils.IsOverseaLightDarkType(poolType))
    CfUtils.SetActive(self.BtnTaskRedPoint, self:CheckPoolHasActivityTaskRed(pool))

    if GachaponUtils.IsGuidType(pool.poolId) then
        CfUtils.SetActive(self.BtnNewNode, true)
        CfUtils.SetActive(self.BtnOne, false)
        CfUtils.SetActive(self.BtnTen, false)
        CfUtils.SetActive(self.BtnTenLock, false)
        
        CfUtils.SetActive(self.SourceOne, false)
        CfUtils.SetActive(self.SourceTen, false)

        CfUtils.SetActive(self.BtnStore, true and self._isUnlockedStore)
        CfUtils.SetActive(self.BtnTipsGroup,false)
        CfUtils.SetActive(self.ActivityRewardNode, false)

        self._jumpToDialog = Constants.UITypeIds.GachaponGuideAnim

        self._autoClose = true

    elseif GachaponUtils.IsNewComerType(poolType) then
        CfUtils.SetActive(self.BtnOne, false)
        -- self.BtnTen.transform.anchoredPosition = Vector2.New(651, -361)

        self.BtnTen:GetComponent(typeof(ButtonComp)).enabled = not lock

        CfUtils.SetActive(self.BtnTenLock, lock)
        CfUtils.SetActive(self.BtnTen.transform:Find("AnimRoot/Unlock"), not lock)
        if lock then
            local lockText = GameUtils.GetUnlockDescr(Constants.CommonUnlockType.PassQuest, pool.unlockQuestId)
            CfUtils.FillText(self.BtnTen.transform:Find("AnimRoot/Lock/FontStyleButton/Text"), lockText)
        end
        CfUtils.SetActive(self.SourceOne, false)
        CfUtils.SetActive(self.SourceTen, true)

        CfUtils.SetActive(self.BtnStore, true and self._isUnlockedStore)
        CfUtils.SetActive(self.BtnTipsGroup, false)

        
        self._jumpToDialog = Constants.UITypeIds.GachaponGuideAnim
        
        self._autoClose = true

        --self.BtnMember.transform:Find("Text").gameObject:GetComponent(typeof(TextComp)).text = localize("武装总览")
      
    elseif GachaponUtils.IsEquipType(poolType) then
        CfUtils.SetActive(self.BtnOne, true)
        CfUtils.SetActive(self.BtnTen, not lock)
        CfUtils.SetActive(self.BtnTenLock, lock)

        CfUtils.SetActive(self.SourceOne, true)
        CfUtils.SetActive(self.SourceTen, true)

        
        CfUtils.SetActive(self.BtnStore, false)
        CfUtils.SetActive(self.BtnTipsGroup, false)

        self._jumpToDialog = Constants.UITypeIds.GachaponCoreAnim

        self._autoClose = false

        --self.BtnMember.transform:Find("Text").gameObject:GetComponent(typeof(TextComp)).text = localize("核心总览")
    elseif GachaponUtils.IsOptionalType(poolType) then
        CfUtils.SetActive(self.BtnOne, true)
        CfUtils.SetActive(self.BtnTen, not lock)
        CfUtils.SetActive(self.BtnTenLock, lock)

        CfUtils.SetActive(self.SourceOne, true)
        CfUtils.SetActive(self.SourceTen, true)

        CfUtils.SetActive(self.BtnStore, true and self._isUnlockedStore)
        CfUtils.SetActive(self.BtnTipsGroup, true)

        self._jumpToDialog = Constants.UITypeIds.GachaponGuideAnim

        self._autoClose = true

    else
        CfUtils.SetActive(self.BtnOne, true)
        CfUtils.SetActive(self.BtnTen, not lock)
        CfUtils.SetActive(self.BtnTenLock, lock)

        CfUtils.SetActive(self.SourceOne, true)
        CfUtils.SetActive(self.SourceTen, true)

        CfUtils.SetActive(self.BtnStore, true and self._isUnlockedStore)
        CfUtils.SetActive(self.BtnTipsGroup, true)

        self._jumpToDialog = Constants.UITypeIds.GachaponGuideAnim

        self._autoClose = true

        if poolType == GachaponConstants.PoolType.OverseaOptional then
            local activityData = checkTable(pool.activity)
            local cardIdList   = checkTable(activityData.choosenCards)
            local isSelected   = #cardIdList > 0
            CfUtils.SetUISwitchImage(self.BtnOne, isSelected and 1 or 2)
            CfUtils.SetUISwitchImage(self.BtnTen.transform:Find("AnimRoot/Unlock/ImgBg"), isSelected and 1 or 2)

        elseif poolType == GachaponConstants.PoolType.OverseaOptionalUp then
            local activityData  = checkTable(pool.activity)
            local choosenCardId = checkInt(activityData.choosenCardId)
            local isSelected    = choosenCardId > 0
            CfUtils.SetUISwitchImage(self.BtnOne, isSelected and 1 or 2)
            CfUtils.SetUISwitchImage(self.BtnTen.transform:Find("AnimRoot/Unlock/ImgBg"), isSelected and 1 or 2)

        elseif poolType == GachaponConstants.PoolType.OverseaLightDark then
            CfUtils.SetActive(self.BtnStore, false)
            CfUtils.SetActive(self.BtnTenUIFX, not lock and GachaponUtils.IsOverseaLightDarkType(poolType))
        
        elseif poolType == GachaponConstants.PoolType.OverseaOnceNovice then
            CfUtils.SetActive(self.BtnOne, false)
            CfUtils.SetActive(self.SourceOne, false)
        end
        
        --self.BtnMember.transform:Find("Text").gameObject:GetComponent(typeof(TextComp)).text = localize("武装总览")
    end
end

-- 刷新抽卡按钮
function GachaponEntry:UpdateBtnInfo(trans, freeData, itemId, consume, updateIcon ,ifDoubleCorn)
    if updateIcon then
        local itemVo = GoodsConfMgr:GetInstance():GetGoodsVoById(itemId)
        if not isNull(itemVo) then
            local img = trans:Find("BtnConsumePop/Image").gameObject:GetComponent(typeof(ImageComp))
            GachaponUtils.LoadSpriteAsync(img, itemVo.photoPath, false)
        end
    end
    local num = consume
    trans:Find("BtnConsumePop/Text2").gameObject:GetComponent(typeof(TMPTextComp)).text = tostring(num)

    if freeData then
        local freeTimes = checkInt(freeData.times)
        if freeTimes <= 0 then
            local timeText = string.fmt(localize('下次免费召唤：_time_'), {_time_ = CfUtils.GetTimeHMS9(freeData.seconds)})
            CfUtils.FillText(trans:Find("FreeTime/TxtTime"), timeText)
        end
        CfUtils.SetActive(trans:Find("BtnConsumePop2"), freeTimes > 0)
        CfUtils.SetActive(trans:Find("BtnConsumePop"), freeTimes <= 0)
        CfUtils.SetActive(trans:Find("FreeTime"), freeTimes <= 0)
    else
        CfUtils.SetActive(trans:Find("BtnConsumePop2"), false)
        CfUtils.SetActive(trans:Find("BtnConsumePop"), true)
        CfUtils.SetActive(trans:Find("FreeTime"), false)
    end
    ifDoubleCorn = checkInt(ifDoubleCorn) 
    if ifDoubleCorn == 0  then
        local img = trans:Find("BtnConsumePop/Image").gameObject:GetComponent(typeof(ImageComp))
        KTool.SetActive(img , true)
        local GoodsAnim = trans:Find("BtnConsumePop/GoodsAnim")
        if isNotNull(GoodsAnim) then
            KTool.SetActive(GoodsAnim , false)
        end
    else 
        local img = trans:Find("BtnConsumePop/Image").gameObject:GetComponent(typeof(ImageComp))
        KTool.SetActive(img , false)
        ---@type UnityEngine.Transform
        local GoodsAnim = trans:Find("BtnConsumePop/GoodsAnim")
        if isNotNull(GoodsAnim) then
            KTool.SetActive(GoodsAnim.gameObject , true)
            local ImgUp2 = GoodsAnim:Find("ImgUp2")
            local imagePath2 = GoodsUtils.GetGoodsIconById(ifDoubleCorn)
            CfUtils.FillImage(ImgUp2 , imagePath2)
            local ImgUp1 = GoodsAnim:Find("ImgUp1")
            CfUtils.FillImage(ImgUp1 , imagePath2)
            local imagePath1 = GoodsUtils.GetGoodsIconById(itemId)
            local ImgDown2 = GoodsAnim:Find("ImgDown2")
            local ImgDown1 = GoodsAnim:Find("ImgDown1")
            CfUtils.FillImage(ImgDown2 , imagePath1)
            CfUtils.FillImage(ImgDown1 , imagePath1)
        end
    end
end

---@param type integer @ 抽卡类型：1 单抽 type 2 十连 
function GachaponEntry:OnGachaponBtn(type)
    ---@type GachaponDojo
    local pool = self.AllGachapon[self._selectIndex + 1]
    if pool.isUnlock == 0 then return end

    local activityData = nil
    if pool:IsValidActivity() then
        if pool.activity.activityUuid then
            local drawCampId = 0
            if GachaponUtils.IsOverseaCampType(pool.poolType) then
                drawCampId = self._selectedCampId
            end
            activityData = {
                activityUuid = pool.activity.activityUuid,
                camp         = drawCampId
            }
        end
            
        local endRemainTime = pool.activity.endRemainTime
        if endRemainTime and checkInt(endRemainTime) <= 0 then
            GameUtils.Toast(localize("抽卡活动已结束"))
            return
        end
    end

    if pool.remainSeconds == 0 then
        GameUtils.Toast(localize("抽卡活动已结束"))
        return
    end

    if pool.poolType == GachaponConstants.PoolType.OverseaOptional then
        local activityData = checkTable(pool.activity)
        local cardIdList   = checkTable(activityData.choosenCards)
        if #cardIdList == 0 then
            GameUtils.Toast(localize("请设定自选战斗员"))
            return
        end
    end

    if pool.poolType == GachaponConstants.PoolType.OverseaOptionalUp then
        local activityData  = checkTable(pool.activity)
        local choosenCardId = checkInt(activityData.choosenCardId)
        if choosenCardId == 0 then
            GameUtils.Toast(localize("请设定UP战斗员"))
            return
        end
    end

    GachaponShared.RecordJump = self._selectIndex
    
    if GachaponUtils.IsOverseaStepType(pool.poolType) then
        GachaponShared.RecordPoolId = pool.poolId
    end
    
    GachaponUtils.CallGachapon(pool, type, activityData, function(response)
        if GachaponUtils.IsOptionalType(pool.poolType) then
            local callTime = 1
            if type == GachaponConstants.CallType.Ten then
                callTime = 10
            end
            pool.activity.callTimes = pool.activity.callTimes + callTime
        elseif GachaponUtils.IsOverseaCoronaType(pool.poolType) then
            local curStepType = pool.activity.stepType
            local curStepNum = pool.activity.stepNum
            self.controller:SetExtraArgument(table.concat({curStepType,"_",curStepNum}))
        end

        -- 如果卡池无效了，则清空当前的位置记录
        if not GachaponUtils.IsPoolValid(pool) then
            GachaponShared.RecordJump = nil
            self._selectIndex = 0
            -- 将列表滚动置顶，避免关闭面板时记录下滚动到中间的位置
            self.Content.anchoredPosition = Vector3(
                self.Content.anchoredPosition.x, 
                0,
                self.Content.anchoredPosition.z
            )
        end

        --[[
            rewardCardResult = {
                { goodsId:string, num:number, convertGoods?:table },
                ...
            }

            statistic = {
                [cardRare:number] = {
                    cnt:number, cardIndexes:number[]
                },
                ...
            }

            rewardTopRare:number
        ]]
        local rewardCardResult, statistic, rewardTopRare = GachaponUtils.CalcGachaponResult(response.data.rewards)
        
        local args = {{id = Constants.UITypeIds.GachaponEntry}}
        if self._jumpToDialog == Constants.UITypeIds.GachaponCoreAnim then
            args = {}
        else
            self._isNeedSkipOnHide = true
        end

        local _activityPoint = checkInt(response.data.activityPoint)
        local openDialogFunc = function()
            local isRookieCall = GachaponUtils.IsNewComerType(pool.poolType)
            GachaponUtils.OpenDialogAction(self._jumpToDialog, { 
                result       = rewardCardResult,
                jumpIndex    = self._selectIndex,
                topRare      = rewardTopRare,
                statistic    = statistic,
                CallType     = type,
                Pool         = pool,
                isRookieCall = isRookieCall,
                taskTipsNode = self._taskTipsNode,
                responseData = response.data,
                activityPoint = _activityPoint
            }, args)
        end

        if GachaponUtils.IsOverseaFriendshipType(pool.poolType) then
            self:UpdatePoolsListRedPoint(self._poolId)
            self:RefreshRedPoint()
            self:RefreshBtnInfo()
            CfUtils.DialogOpen(Constants.UITypeIds.GachaponFriendshipResultDialog, {result = rewardCardResult, needReopenCb = function()
                local initParams = CfUtils.DialogSafeParameters(self.controller)
                initParams.reopenFriendshipResultData = rewardCardResult
            end})
            return
        end

        if self._isNeedSkipOnHide and not Config.DEBUG_QUICK_START then
            self:PreloadAssets(pool)
            self:PoolVideoStop_()
            self:PlayOpeningMovie(function()
                openDialogFunc()
            end)
        else
            openDialogFunc()
        end
        if GachaponUtils.IsGuidType(pool.poolId) then
            xRecord.adjust_internal({event = "newplayer02"})
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            xRecord.facebook_internal("fb_mobile_level_achieved", {playerId = tostring(playerComponent:GetPlayerDojo().playerId)})
        end
    end)
end


function GachaponEntry:PoolVideoStop_()
    CfUtils.SetActive(self.VideoPreview, false)
    -- CfUtils.SetActive(self.AdmissionPanel, true)
    self.VideoPreviewBg.anchoredPosition = Vector2.New(-999999, -999999)

    if self.VideoPreviewMovie.player then
        self.VideoPreviewMovie:Stop()  -- 当前帧不会立刻变为 stop 状态
        self.VideoPreviewMovie.player:StopForSeek()
        self.VideoPreviewMovie.player:SetSeekPosition(0)
    end
end


function GachaponEntry:PoolVideoPlay_(videoName)
    CfUtils.SetActive(self.VideoPreview, true)
    -- CfUtils.SetActive(self.AdmissionPanel, false)
    self.VideoPreviewBg.anchoredPosition = Vector2.New(0, 0)

    if self.VideoPreviewMovie.loop == false then
        self.VideoPreviewMovie.loop = true
    end
    if self.VideoPreviewMovie.player.statusChangeCallback == nil then
        self.VideoPreviewMovie.player.statusChangeCallback = function(status)
            if status == CS.CriWare.CriMana.Player.Status.Stop then
                local tempVideoName = self.tempVideoName_
                if tempVideoName ~= nil then
                    self.tempVideoName_ = nil
                    self:PoolVideoPlay_(tempVideoName)
                end
            end
        end
    end

    -- 如果播放器 还未变到 停止状态：则先记录要播放的视频名，让播放器停止掉，等待播放器状态变为停止视，再播放才能正常。
    if self.VideoPreviewMovie.player and self.VideoPreviewMovie.player.status ~= CS.CriWare.CriMana.Player.Status.Stop then
        self.tempVideoName_ = videoName
        self.VideoPreviewMovie:Stop()  -- 当前帧不会立刻变为 stop 状态
    else
        local poolVideoPath = GameUtils.GetManaPath(string.fmt("Movie/%1.usm", videoName))
        self.VideoPreviewMovie.player:SetFile(nil, poolVideoPath)
        self.VideoPreviewMovie:Play()  -- 当前帧不会立刻变为 play 状态
    end
end


