function GachaponEntry:PreloadMovie()
    self.ContentBg.anchoredPosition = Vector2.New(-999999, -999999)

    ---@type UnityEngine.GameObject
    local contentBg = GameObject.Instantiate(self.ContentBg.gameObject)
    contentBg.transform:SetParent(self.ContentBg.transform.parent.parent)
    contentBg.transform.localPosition = Vector3.New(0, 0, 0)
    contentBg.transform.localScale    = Vector3.New(1, 1, 1)
    contentBg.name = 'GachaponEntryBg'
    GachaponShared:SetTempContent(contentBg)
    
    ---@type UnityEngine.RectTransform
    self.ContentBg = contentBg:GetComponent(typeof(RectTransform))
    self.ContentBg.anchoredPosition = Vector2.New(-999999, -999999)

    ---@type CriWare.CriManaMovieControllerForUI
    self.MovieControllerUI = contentBg.transform:Find('Movie'):GetComponent(typeof(CriManaMovieControllerForUI))

    local controllerForUI = self.MovieControllerUI
    controllerForUI.player:SetFile(nil, GameUtils.GetManaPath("Movie/gachapon_open_door.usm"))
    controllerForUI.player:Prepare()
end


---@param pool GachaponDojo
function GachaponEntry:PreloadAssets(pool)

    -------------------------------------------------
    local preloadDict = {}

    -- load hand model
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent) or {}
    local isFemalePlayer  = playerComponent.playerDojo and (checkInt(playerComponent.playerDojo.gender) == Constants.PLAYER_GENDER.FEMALE)
    local handPrefabPath  = string.format(GachaponConstants.GachaponGuideAnimHandPath, isFemalePlayer and 'f' or 'm')
    preloadDict[handPrefabPath] = true
    
    -- load scene model
    -- local scenePrefabPath = GachaponConstants.GachaponGuideAnimScenePath
    -- preloadDict[scenePrefabPath] = true

    -- load ball model
    local ballPrefabPath = GachaponConstants.GachaponGuideAnimBallPath
    preloadDict[ballPrefabPath] = true
    for _, typeBallPrefabPath in pairs(GachaponConstants.GachaponGuideAnimBallTypePath) do
        preloadDict[typeBallPrefabPath] = true
    end
    
    -- load bead models
    for _, beadPrefabPath in pairs(GachaponConstants.GachaponGuideAnimBeadPath) do
        preloadDict[beadPrefabPath] = true
    end
    
    -- all timelien prefabs
    for defineKey, tlDefine in pairs(GachaponConstants.GachaponGuideAnimTLDefine) do
        if tlDefine.PREFAB and tlDefine.PRELOAD then
            if pool ~= nil and GachaponUtils.IsOverseaLightDarkType(pool.poolType) and tlDefine.PREFAB_L ~= nil then
                preloadDict[tlDefine.PREFAB_L] = true
            else
                preloadDict[tlDefine.PREFAB] = true
            end
        end
    end

    -- to preload assets
    for prefabPath, _ in pairs(preloadDict) do
        if CfUtils.IsBundleResourceExist(prefabPath) then
            GachaponShared:LoadModelAsync(prefabPath)
        end
    end 
end


function GachaponEntry:PlayOpeningMovie(finishCB)
    CfUtils.SetTopActive(false)
    self.ContentBg.anchoredPosition = Vector2.New(0, 0)
    CfUtils.SetActive(self.ContentRoot, false)
    CfUtils.SetActive(self.bg, false)

    -- 隐藏手和手机，避免出现影片前能看到一帧的模型
    local timelinePath = GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_0.PREFAB
    local timelineObj  = GachaponShared:GetModel(timelinePath)
    local handParent   = isNotNull(timelineObj) and timelineObj.transform:Find(GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_0.HAND_PLACE) or nil
    CfUtils.SetActive(handParent, false)

    ---@type CriWare.CriManaMovieControllerForUI
    local controllerForUI = self.MovieControllerUI
    -- 正在播放中 ，直接return
    if controllerForUI.player.status == CS.CriWare.CriMana.Player.Status.Playing then
        return
    end

    controllerForUI.player.statusChangeCallback = function(status)
        if status == CS.CriWare.CriMana.Player.Status.Ready then
        elseif status == CS.CriWare.CriMana.Player.Status.PlayEnd then
        end
    end

    controllerForUI:Play()
    -- 先暂停携程
    if self._openDoorCo then
        cs_coroutine.stop(self._openDoorCo)
        self._openDoorCo = nil
    end

    self._openDoorCo = cs_coroutine.start(function()
        local frameInfo = controllerForUI.player.frameInfo
        local count = frameInfo and frameInfo.totalFramesPerFile - 1 or 0
        local zero = frameInfo and frameInfo.frameNoPerFile or 0
        local isPlay = false
        while zero < count do
            if (not frameInfo) or (not frameInfo.frameNoPerFile)  then
                break
            end
            -- 到第二针开始播放声音
            if zero > 1 and not isPlay then
                CriWareUtils.SetVolume(Constants.CriWareCategory.BGM, 0)
                -- CriWareUtils.PlaySeById(GachaponConstants.GachaponSE.OpenDoor)
                isPlay = true
            end
            zero = frameInfo.frameNoPerFile
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end
        zero = 0
        -- controllerForUI:Stop()
        -- controllerForUI.player:StopForSeek()
        -- controllerForUI.player:SetSeekPosition(0)
        if finishCB then
            finishCB()
        end
    end)
end

function GachaponEntry:PlayOpeningTimeline()
    local loadedObjects = {}

    local LoadPrefabModel = function(prefabPath, isDelAnimator)
        GachaponShared:LoadModel(prefabPath)
        while not GachaponShared:GetModel(prefabPath) do
            CoYield()
        end
        self._loadedObjects[prefabPath] = true

        if isDelAnimator then
            ---@type UnityEngine.GameObject
            local prefabModel = GachaponShared:GetModel(prefabPath)
            ---@type UnityEngine.Animator
            local catAnimator = prefabModel:GetComponent(typeof(Animator))
            if not isNull(catAnimator) then
                catAnimator.runtimeAnimatorController = nil
            end
        end
    end

    -- enable blocker
    UIRaycastBlocker:AddCondition(OPENING_BLOCKER_NAME)

    if self._openCo ~= nil then
        cs_coroutine.stop(self._openCo)
    end
    
    self._openCo = cs_coroutine.start(function()

        ------------------------------------------------- [load models]
        -- load timeline
        local timelinePath = GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_0.PREFAB
        LoadPrefabModel(timelinePath)
        
        -- init timeline
        local timelineObj = GachaponShared:GetModel(timelinePath)

        -- load player hand
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent) or {}
        local isFemalePlayer  = playerComponent.playerDojo and (checkInt(playerComponent.playerDojo.gender) == Constants.PLAYER_GENDER.FEMALE)
        local handPrefabPath  = string.format(GachaponConstants.GachaponGuideEntryHandPath, isFemalePlayer and 'f' or 'm')
        LoadPrefabModel(handPrefabPath, true)

        -- init player hand
        local handObject = GachaponShared:GetModel(handPrefabPath)
        
        -- add hand
        local handParent = timelineObj.transform:Find(GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_0.HAND_PLACE)
        handObject.transform:SetParent(handParent, false)

        -- track hand
        ---@type UnityEngine.Playables.PlayableDirector
        local tlDirector = timelineObj:GetComponent(typeof(PlayableDirector))
        GachaponUtils.BindTimeline(tlDirector, GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_0.HAND_TRACK, handObject)

        
        ------------------------------------------------- [init timeline]
        -- set camera
        local cameraPath = GachaponConstants.GachaponGuideAnimTLDefine.TIMELINE_0.CAMERA
        local originCam  = timelineObj.transform:Find(cameraPath).gameObject
        local cameraComp = originCam.gameObject:GetComponent(typeof(Camera))
        --URPCameraController:SetMainCameraActive(false)
        CfUtils.SetActive(URPCameraController.mainCamera, false)
        --cs_coroutine.yield_return(Yielders.EndOfFrame)
        --CfUtils.SetActive(URPCameraController.mainCamera, false)
        URPCameraController:InitCameraStack(cameraComp)
        --self._gachaCam = cameraComp
        
        
        ------------------------------------------------- [play timeline]
        CfUtils.SetActive(handParent, true)
        CfUtils.SetActive(timelineObj, true)
        CfUtils.SetActive(handObject, true)
        
        tlDirector.time = 0
        tlDirector:Play()
        
        CoYield() -- 播放1帧后再暂停，用于给tl初始化，不然一上来就暂停，tl显示是异常的
        tlDirector:Pause()

        UIRaycastBlocker:RemoveCondition(OPENING_BLOCKER_NAME)

    
        ------------------------------------------------- [request data]
        local callHomeData = nil
        GameUtils.Request(Interfaces.CallHome, {}, function(request, response)
            if checkInt(response.errCode) == 0 then
                callHomeData = response.data
            end
        end)

        while not callHomeData do
            CoYield()
        end

        local gachaponComp = GachaponUtils.GetGachaponComp()
        gachaponComp:InitialGachapon(callHomeData)

        -- do init
        self:DoInitialize_()

        -- play timeline
        tlDirector:Play()

        -- show ui
        self:InitStep_()
        
        CoYield(tlDirector.duration)

        self._openCo = nil

        Events.Broadcast(Constants.EventNames.EVENT_GUIDE_WAIT_ANIMATE_EXECUTE_COMPLETE)
    end)
end

local function Clamp(min, val, max) 
    local reVal
    if val > max then
        reVal = max
    elseif val < min then
        reVal = min
    else
        reVal = val
    end
    return reVal
end

function GachaponEntry:UpdateHandler()
   
    if checkNumber(GuideUtils.GetCurTriggerModuleId()) == Constants.GuideModule.Gachapon then 
        return 
    end
    local gyro = Input.gyro.attitude
    local x =  Clamp(GachaponConstants.GyroRange.x.min, gyro.x * 100, GachaponConstants.GyroRange.x.max)
    local y =  Clamp(GachaponConstants.GyroRange.y.min, gyro.y * 100, GachaponConstants.GyroRange.y.max)
    self.controller.transform:Find("Container").transform.rotation = Quaternion.Euler(x, y, 0)
end


function GachaponEntry:OnCommonMainlineTaskTipsNodeHandler_(data)
    self._taskTipsNode = data and data.luaEnv or nil
    if self._taskTipsNode then
        CfUtils.SetActive(self._taskTipsNode.controller.transform, false)
    end
end


function GachaponEntry:OnCFreeTimesCountdownHandler_()
    if self.AllGachapon == nil or self._selectIndex == nil then
        return
    end
    ---@type GachaponDojo
    local pool = self.AllGachapon[self._selectIndex + 1]
    if pool and pool.freeData then
        self:RefreshBtnInfo()
    end
end

function GachaponEntry:OnBtnFeedbackClick(pool)
    GachaponShared.RecordJump = self._selectIndex
    UIModule.OpenDialog({ id = Constants.UITypeIds.GachaponComTaskDialog , parameters = { pool = pool}})
end

function GachaponEntry:CheckPoolHasFeedBackTaskRed(pool)
    local isShowFeedBack = isSet(pool,"feedbackTasks") and (table.count(pool.feedbackTasks) > 0)
    if isShowFeedBack then
        for i, v in pairs(pool.feedbackTasks) do
            if v.status == Constants.GetStatus.Can then
                return true
            end
        end
    end
    return false
end

function GachaponEntry:RefreshFeedBackRedPoint()
    if self._selectIndex then
        local pool = self.AllGachapon[self._selectIndex + 1]
        if isNotNull(pool) then
            self:UpdatePoolsListRedPoint(pool.poolId)
            local isShowFeedBack = isSet(pool,"feedbackTasks") and (table.count(pool.feedbackTasks) > 0)
            if isShowFeedBack then
                local hasFeedBackRed = self:CheckPoolHasFeedBackTaskRed(pool)
                local redGo = GameUtils.GetRedPointGo(self.BtnFeedback)
                CfUtils.SetActive(redGo,hasFeedBackRed)
            end
        end
    end
end

function GachaponEntry:OnBtnDrawStepClick()
    self:OnGachaponBtn(GachaponConstants.CallType.Ten)
end

return GachaponEntry
